<?php
$id=(int)($_GET['id']??0);
echo '<div class="page-head"><div><h1>Inventory Count'.($id?' Review':' History').'</h1><p>Download filtered stock sheets, upload actual counts, then review and approve adjustments.</p></div><a class="btn ghost" href="?page=stocks">Current Stocks</a></div>';
if(!$id){
 $offset=max(0,(int)($_GET['offset']??0));$total=(int)$pdo->query('SELECT COUNT(*) FROM inventory_count_batches')->fetchColumn();echo '<div class="card table-wrap"><table class="table"><tr><th>Reference</th><th>Created</th><th>Created By</th><th>Status</th><th>Reviewed By</th><th>Approved By</th><th>Action</th></tr>';foreach($pdo->query("SELECT * FROM inventory_count_batches ORDER BY id DESC LIMIT 50 OFFSET $offset") as $batch)echo '<tr><td>'.e($batch['batch_ref']).'</td><td>'.e($batch['created_at']).'</td><td>'.e($batch['created_name'].' – '.$batch['created_role']).'</td><td>'.badge($batch['status'],status_badge_class($batch['status'])).'</td><td>'.e(($batch['reviewed_name']??'').' '.($batch['reviewed_role']??'')).'</td><td>'.e(($batch['approved_name']??'').' '.($batch['approved_role']??'')).'</td><td><a class="btn ghost sm" href="?page=inventory_count&id='.$batch['id'].'">View</a></td></tr>';echo '</table></div><div class="modal-actions">';if($offset>0)echo '<a class="btn ghost" href="?page=inventory_count&offset='.max(0,$offset-50).'">Previous</a>';if($offset+50<$total)echo '<a class="btn ghost" href="?page=inventory_count&offset='.($offset+50).'">Next</a>';echo '</div>';
}else{
 try{$batch=count_batch($id);$lines=count_lines($id);$errors=json_decode($batch['error_json']??'[]',true)?:[];
 echo '<div class="card"><div class="card-head"><h3>'.e($batch['batch_ref']).'</h3>'.badge($batch['status'],status_badge_class($batch['status'])).'</div><p>Count Date: '.e($batch['count_date']??substr($batch['created_at'],0,10)).' · Snapshot: '.e($batch['created_at']).' · '.e($batch['created_name'].' – '.$batch['created_role']).'</p><p>On Hand = sellable + non-sellable. Variance = Actual Count − snapshot On Hand. Blank counts are skipped. Adjustments change sellable stock and the reviewed platform quantities. New sheets separate Actual Good and Actual Damaged. Condition changes are reviewed and recorded; legacy sheets retain their original Non-Sellable balance.</p><div class="modal-actions"><a class="btn ghost" href="inventory_count.php?id='.$id.'&download=1">Download Original Sheet</a><a class="btn ghost" target="_blank" href="inventory_count.php?id='.$id.'&print=1">Print Sheet</a><a class="btn ghost" href="?page=inventory_count">Count History</a></div></div>';
 if($errors){echo '<div class="alert danger"><b>Review Errors</b><ul>';foreach($errors as $message)echo '<li>'.e($message).'</li>';echo '</ul></div>';}
 if(!in_array($batch['status'],['Applied','Cancelled','Reversed'],true)&&can_action('upload_inventory_count'))echo '<div class="card"><h3>Upload Actual Counts</h3><p>Fill the yellow Actual Good / Actual Damaged / Remarks cells in the original XLSX. Zero means counted zero; blank means not counted. Variance is computed by the system.</p><form action="inventory_count.php" method="post" enctype="multipart/form-data" class="inline-form"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="action" value="upload"><input type="hidden" name="batch_id" value="'.$id.'"><input type="file" name="file" accept=".xlsx" required><button class="btn primary">Upload & Review</button></form></div>';
 echo '<div class="card table-wrap"><table class="table"><tr><th>Master SKU</th><th>Product Description</th><th>On Hand</th><th>Actual Good</th><th>Actual Damaged</th><th>Actual Total</th><th>Good / Damaged Variance</th><th>Variance</th><th>Remarks</th><th>Review</th></tr>';foreach($lines as $line){$changed=!hash_equals($line['stock_signature'],count_stock_signature($line['product_id']));$label=$line['actual_count']===null?'Not counted':($changed&&$batch['status']!=='Applied'?'Stock changed — refresh sheet':((int)$line['variance']===0?(($line['good_variance']??0)||($line['damaged_variance']??0)?'Condition discrepancy':'Matched'):((int)$line['variance']>0?'Overage':'Shortage')));echo '<tr><td>'.e($line['master_sku']).'</td><td>'.e($line['product_name']).'</td><td>'.(int)$line['on_hand'].'</td><td>'.e($line['actual_good']??'—').'</td><td>'.e($line['actual_damaged']??'—').'</td><td>'.($line['actual_count']===null?'—':(int)$line['actual_count']).'</td><td>'.e(($line['good_variance']??'—').' / '.($line['damaged_variance']??'—')).'</td><td>'.($line['variance']===null?'—':((int)$line['variance']>0?'+':'').(int)$line['variance']).'</td><td>'.e($line['remarks']).'</td><td>'.e($label).'</td></tr>';}echo '</table></div>';
 if(in_array($batch['status'],['Pending Review','Review Only'],true)&&can_action('upload_inventory_count')){
  echo '<div class="card"><h3>Review Decision</h3><form action="inventory_count.php" method="post"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="action" value="review_only"><input type="hidden" name="batch_id" value="'.$id.'"><button class="btn ghost">Save Review Only</button></form>';
  if(current_user()['role']==='Admin'){echo '<form action="inventory_count.php" method="post" class="stack" data-confirm="Apply these inventory count adjustments? Only counted rows will change. Good and Damaged quantities will be adjusted separately as reviewed. The entered platform adjustment quantities will be applied."><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="action" value="apply"><input type="hidden" name="batch_id" value="'.$id.'">';count_platform_adjustment_form($lines);echo '<label>Adjustment Reason<textarea name="reason" required></textarea></label><label class="ack"><input type="checkbox" name="review_ack" value="1" required> I reviewed the actual counts and approve these adjustments.</label><button class="btn primary">Apply Inventory Adjustment</button></form>';}else echo '<p>Administrator approval is required to apply adjustments.</p>';echo '</div>';
 }
 if(!in_array($batch['status'],['Applied','Cancelled','Reversed'],true)&&can_action('upload_inventory_count'))echo '<div class="card"><form method="post" action="inventory_count.php" data-confirm="Cancel this pending inventory count? No stock will change."><input type="hidden" name="action" value="cancel"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="batch_id" value="'.$id.'"><button class="btn ghost">Cancel Count</button></form></div>';
 if($batch['status']==='Applied')echo '<div class="card"><h3>Approval Record</h3><p>'.e($batch['approved_name'].' – '.$batch['approved_role']).' · '.e($batch['applied_at']).'</p><p>Reason: '.e($batch['reason']).'</p><p>Physical Before → After values and variances are retained in this record. Blank rows were not adjusted.</p></div>';
 }catch(Throwable $error){echo '<div class="alert danger">'.e($error->getMessage()).'</div>';}
}
